def normalize_before(text):
    return text.strip().lower()

def normalize_after(text):
    return text.lower()

samples = [" A ", "B"]
before_outputs = [normalize_before(text) for text in samples]
after_outputs = [normalize_after(text) for text in samples]
before = len(before_outputs)
after = len(after_outputs)
count_ok = after >= before
print(count_ok, repr(before_outputs[0]), repr(after_outputs[0]))

